// ---- 第279便a(原仮定者の裁定(第69報)「各サンプルについて目的と状況を一覧化する」・R60): docs.sampleStatus-sync ----
// ----   一覧 docs/SAMPLE_STATUS_v1.45.md(生成物)と、html の生成領域 sample-status(表)と、正本
// ----   tests/out/samplestatus-w279a.json の 3 者が一致することを fs だけで固定する:
// ----     ① md の表の行数 = html の表の行数 = 正本 rows の数(= 内蔵本数)・ID の集合が同じ。
// ----     ② md の各行の較正の語 = html の表の calibration の語(4 値の正式語・判定保留(量定義不一致)・較正対象外)。
// ----     ③ md の集計行(状況 達/部分/未達・4 値・判定保留・較正対象外)= 正本の tally = html の表から数え直した値。
// ----     ④ 正本の status が html の表と 1 字も違わない(表を手で直すと食い違う)。
// ----     ⑤ md に禁止語が無い(否定文でも書かない)。
// ----     ⑥ 第283便e(原仮定者の裁定(第73報)・統括の検証項目 R88): 所要時間の節の QA 帰属は **claims の testId + 原稿の明示
// ----        qaTargets** だけ(部分文字列の一致をやめた)。qaTargets の本は内蔵にある・galaxy←galaxyStd・earthMoonReal←KF1・
// ----        bhCore←Tilt の混入が新規則で 0(旧規則の本数を記録)・正本が新しい帰属で作られていれば本数が再計算と一致。
// ----   **対象 html に生成領域 sample-status が無ければ SKIP**(root 等の旧世代)。
{
  const html = fs.readFileSync(path.join(ROOT, TARGET), 'utf8');
  if (html.indexOf('// >>> w275a-generated: sample-status') < 0) {
    console.log('SKIP docs.sampleStatus-sync(対象 html に第279便a の生成領域 sample-status なし — root 等)');
  } else {
    const bad = [];
    let nMd = 0, nHtml = 0, nCanon = 0, tl = null, cases6 = '';
    try {
      const SS = await import('file://' + path.join(ROOT, 'tests', 'lib-w279a-samplestatus.mjs'));
      const reg = SS.parseRegion(html);
      if (!reg) throw new Error('生成領域が読めない');
      const T = reg.table;
      nHtml = Object.keys(T).length;
      const md = fs.readFileSync(path.join(ROOT, 'docs', 'SAMPLE_STATUS_v1.45.md'), 'utf8');
      const J = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'out', 'samplestatus-w279a.json'), 'utf8'));
      const rows = SS.parseMdRows(md);
      nMd = rows.length; nCanon = (J.rows || []).length;
      if (!(nMd === nHtml && nHtml === nCanon)) bad.push(`①行数 md ${nMd}・html ${nHtml}・正本 ${nCanon}`);
      const idsMd = new Set(rows.map((z) => z.id));
      for (const id of Object.keys(T)) if (!idsMd.has(id)) bad.push('①md に無い ' + id);
      for (const z of rows) {
        if (!T[z.id]) { bad.push('①html に無い ' + z.id); continue; }
        if (z.cal !== SS.CAL_WORD.ja[T[z.id].calibration]) bad.push(`②${z.id}: md「${z.cal}」≠ html ${T[z.id].calibration}`);
      }
      tl = SS.tally(T, []);
      const jt = J.tally || {};
      const eqo = (a, b) => JSON.stringify(a) === JSON.stringify(b);
      if (!eqo(jt.objective, tl.objective)) bad.push('③正本 tally.objective ≠ html');
      if (!eqo(jt.four, tl.four)) bad.push('③正本 tally.four ≠ html');
      if (!eqo(jt.calibration, tl.calibration)) bad.push('③正本 tally.calibration ≠ html');
      const want = `状況: **達 ${tl.objective.met}・部分 ${tl.objective.partial}・未達 ${tl.objective.unmet}・対象外 ${tl.objective['n/a']}**`;
      if (md.indexOf(want) < 0) bad.push('③md の状況の集計行 ≠ html');
      const want4 = `**${tl.four['合']}/${tl.four['量限定合']}/${tl.four['否']}/${tl.four['保留']}**(台帳の転記)・判定保留(量定義不一致)**${tl.calibration['hold-definition']}**・較正対象外 **${tl.calibration['out-of-scope']}**`;
      if (md.indexOf(want4) < 0) bad.push('③md の較正の集計行 ≠ html');
      for (const z of J.rows || []) if (JSON.stringify(z.status) !== JSON.stringify(T[z.id])) bad.push('④正本の status ≠ html ' + z.id);
      for (const line of md.split('\n')) {
        const bare = line.replace(/[「『][^」』]*[」』]/g, '');
        if (SS.FORBIDDEN.test(bare)) bad.push('⑤禁止語: ' + line.slice(0, 40));
      }
      // ⑥ 第283便e(原仮定者の裁定(第73報)・統括の検証項目 R88): 所要時間の節の QA 帰属は claims の testId + 原稿の明示 qaTargets だけ
      if (typeof SS.qaAttribution === 'function') {
        const src = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'data-w279a-samplestatus-src.json'), 'utf8'));
        const qt = (src.qaTargets || {});
        if (qt.version !== SS.QA_ATTRIBUTION_VERSION) bad.push('⑥原稿の qaTargets の版 ' + qt.version + ' ≠ ' + SS.QA_ATTRIBUTION_VERSION);
        const tt = qt.tests || {};
        for (const [tid, ids] of Object.entries(tt)) {
          if (!Array.isArray(ids) || !ids.length) { bad.push('⑥qaTargets の ' + tid + ' に本が無い'); continue; }
          for (const id of ids) if (!T[id]) bad.push('⑥qaTargets の ' + tid + ' が内蔵に無い本 ' + id + ' を挙げる');
        }
        const L = (await import('file://' + path.join(ROOT, 'tests', 'lib-w279b-headless.mjs'))).loadHtmlHeadless(path.join(ROOT, TARGET));
        const rowsP = L.evalExpr('BUILTIN_PRESETS').map((p) => ({ id: p.id, claimTests: Array.isArray(p.claims) ? [...new Set(p.claims.map((c) => c.testId).filter(Boolean))] : [] }));
        const QA = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'out', 'qa-results-full-beta.json'), 'utf8'));
        const A = SS.qaAttribution(rowsP, src, QA.results || []);
        const OLD = SS.qaAttributionLegacy(rowsP, QA.results || []);
        const pairs = [['galaxy', 'galaxyStd'], ['earthMoonReal', 'earthMoonRealKF1'], ['bhCore', 'bhCoreTilt']];
        const mixTxt = [];
        for (const [a, b] of pairs) {
          if (!A.byId[a]) { bad.push('⑥内蔵に無い ' + a); continue; }
          const leak = A.byId[a].tests.filter((t) => t.id.toLowerCase().includes(b.toLowerCase()) && !(tt[t.id] || []).includes(a)
            && !(rowsP.find((z) => z.id === a).claimTests.includes(t.id)));
          if (leak.length) bad.push(`⑥${a} に ${b} の試験が混入: ${leak.map((t) => t.id).join(',')}`);
          const oldN = (OLD[a] || []).filter((t) => t.toLowerCase().includes(b.toLowerCase())).length;
          mixTxt.push(`${a}←${b} 旧 ${oldN}・新 ${leak.length}`);
        }
        const mix = SS.qaLegacyMixing(rowsP, src, QA.results || []);
        // 正本が新しい帰属で作られていれば(版と保存 QA の commit が同じとき)、本ごとの本数が今の再計算と一致する
        const tn = (J.timingNote || {}).qaAttribution || null;
        const ev = (J.meta || {}).evidenceQa || {};
        let cmp = '正本は旧帰属(統合時の samplestatus の段で入れ替わる)';
        if (tn && tn.version === SS.QA_ATTRIBUTION_VERSION) {
          if (ev.commit === (QA.commit || null) && ev.date === (QA.date || null)) {
            const off = (J.rows || []).filter((z) => !z.timing || !z.timing.qa || !A.byId[z.id] || z.timing.qa.n !== A.byId[z.id].n || z.timing.qa.attributed !== A.byId[z.id].attributed);
            if (off.length) bad.push('⑥正本の QA 帰属の本数が再計算と違う: ' + off.slice(0, 4).map((z) => z.id).join(','));
            cmp = `正本の帰属 ${J.rows.length - off.length}/${J.rows.length} 本が再計算と一致`;
            if (md.indexOf('qaTargets') < 0) bad.push('⑥md の保存 QA の説明に qaTargets が無い');
          } else cmp = '保存 QA が正本の生成後に更新された(本数の照合は飛ばす)';
        }
        cases6 = `QA 帰属 ${A.version}: qaTargets ${Object.keys(tt).length} 試験・帰属なし ${A.unattributed.length} 本・${mixTxt.join(' / ')}・旧規則の混入 ${mix.length} 組(${new Set(mix.map((z) => z[0])).size} 本)は新規則で 0・${cmp}`;
      }
    } catch (e) { bad.push('読めない: ' + String(e).slice(0, 90)); }
    add('docs.sampleStatus-sync', bad.length === 0,
      `**サンプル状況一覧 ↔ html ↔ 正本**(第279便a): 行数 md ${nMd}・html ${nHtml}・正本 ${nCanon}` +
      (tl ? ` / 状況 達 ${tl.objective.met}・部分 ${tl.objective.partial}・未達 ${tl.objective.unmet} / 4 値 ${Object.values(tl.four).join('/')}` +
        `・判定保留(量定義不一致)${tl.calibration['hold-definition']}・較正対象外 ${tl.calibration['out-of-scope']}` : '') +
      (cases6 ? ' / ' + cases6 : '') +
      (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.slice(0, 5).join(' , ')}` : ' / 3 者一致・禁止語 0'));
  }
}

// ---- 第283便b(原仮定者の裁定(第73報)④「同一天体の似た内容のサンプルを統廃合する(内容を比較して提案)」・統括の検証項目 R85): docs.families ----
// ----   家族の差分表(器 tests/exp-w283b-families.mjs・正本 tests/out/families-w283b.json・一覧 docs/FAMILIES_v1.45.md)を fs だけで固定する:
// ----     ① 正本の家族は器の宣言(FAMILIES)と同じ並び・同じ本数(pluto 6・earthmoon 6・mercury 3・saturn 5・psr 6/3/3/3・gw 4 …)。
// ----     ② 一覧 md は正本から器の renderMd で作り直したものと 1 字も違わない(手で直すと食い違う)。
// ----     ③ md に禁止語が無い(「統合した」「観測一致を達成した」等 —— 候補であって実行ではない)。
// ----     ④ 候補(規則 A/B)の「残す」と「畳む」が較正の派生値 kF0 版 / DFM 版をまたがない(観測版と DFM 版を 1 ID にしない)・
// ----        規則 C は「残す」を持たない(要裁定の印だけ)。
// ----     ⑤ **畳んでいない**: 候補の「畳む」本はすべて対象 html の BUILTIN_PRESETS に残っている。
// ----     ⑥ 退役 7 本の棚卸し: 7 本とも内蔵に残り退役の印があり、内蔵と凍結の写しの presetSigHash が同じ。
// ----   **対象 html に第283便b の退役の語彙(FAMILY_ROLES)が無ければ SKIP**(root 等)。
{
  const html = fs.readFileSync(path.join(ROOT, TARGET), 'utf8');
  if (html.indexOf('const FAMILY_ROLES=') < 0) {
    console.log('SKIP docs.families(対象 html に第283便b の FAMILY_ROLES なし — root 等)');
  } else {
    const bad = [];
    let J = null, E = null;
    try {
      E = await import('file://' + path.join(ROOT, 'tests', 'exp-w283b-families.mjs'));
      J = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'out', 'families-w283b.json'), 'utf8'));
      const md = fs.readFileSync(path.join(ROOT, 'docs', 'FAMILIES_v1.45.md'), 'utf8');
      // ①
      const want = E.FAMILIES.map((F) => F.key + ':' + F.ids.length).join(',');
      const got = (J.families || []).map((F) => F.key + ':' + F.rows.length).join(',');
      if (want !== got) bad.push(`①家族の並び・本数 ${got} ≠ 宣言 ${want}`);
      for (const F of J.families || []) for (const r of F.rows) if (r.missing) bad.push('①内蔵に無い本 ' + r.id);
      if (!J.meta || J.meta.wave !== '第283便b' || J.meta.provenanceVersion !== 'w272e-1') bad.push('①正本の来歴が第283便b / w272e-1 でない');
      // ②
      if (E.renderMd(J) !== md) bad.push('②md が正本から作り直したものと違う');
      // ③
      const badLines = md.split('\n').filter((l) => E.MD_FORBIDDEN.test(l.replace(/[「『][^」』]*[」』]/g, '')));
      if (badLines.length) bad.push('③禁止語: ' + badLines[0].slice(0, 40));
      // ④
      for (const F of J.families || []) {
        const cv = Object.fromEntries(F.rows.map((r) => [r.id, r.calVariant]));
        for (const z of F.candidates) {
          if (z.rule === 'C') { if (z.keep !== null) bad.push(`④${F.key}: 規則 C に残す本がある`); continue; }
          for (const f of z.fold) if (cv[z.keep] && cv[f] && cv[z.keep] !== cv[f]) bad.push(`④${F.key}: ${z.keep}(${cv[z.keep]})と ${f}(${cv[f]})を畳む候補`);
        }
      }
      // ⑤
      const block = html.match(/const BUILTIN_PRESETS = \[([\s\S]*?)\n\];/);
      const ids = new Set(block ? [...block[1].matchAll(/\{ id:"(\w+)"/g)].map((x) => x[1]) : []);
      const folds = (J.families || []).flatMap((F) => F.candidates.flatMap((z) => z.fold));
      for (const f of folds) if (!ids.has(f)) bad.push('⑤候補の本が内蔵から消えている ' + f);
      // ⑥
      const R = J.retired || {};
      // 第284便b(原仮定者の裁定(第74報)⑤・AN35): 退役 6 本を足して 13 本(世代切替 —— RETIRED_PRESETS に 🪶 の行)
      const nRet = html.indexOf('  psrDoubleABPN:{ja:') >= 0 ? 13 : 7;
      if (!(Array.isArray(R.presets) && R.presets.length === nRet)) bad.push(`⑥退役の棚卸しが ${nRet} 本でない`);
      for (const p of R.presets || []) {
        if (!p.inBuiltin || !p.retired) bad.push(`⑥${p.id}: 内蔵に無い/退役の印が無い`);
        if (!(p.sigBuiltin && p.sigBuiltin === p.sigFixture && p.sigFixtureNow === p.sigFixture)) bad.push(`⑥${p.id}: 署名 内蔵 ${p.sigBuiltin} / 写し ${p.sigFixture}`);
      }
    } catch (e) { bad.push('読めない: ' + String(e).slice(0, 100)); }
    const c = (J && J.counts) || {};
    add('docs.families', bad.length === 0,
      `**同一天体の家族の差分表**(第283便b・原仮定者の裁定(第73報)④・R85): 家族 ${c.families}・本 ${c.members}(退役 ${c.retiredMembers})` +
      ` / 推定の列 主系列 ${(c.role || {})['主系列']}・比較 ${(c.role || {})['比較']}・診断 ${(c.role || {})['診断']}・履歴 ${(c.role || {})['履歴']}` +
      ` / 候補 A ${(c.cand || {}).A || 0}・B ${(c.cand || {}).B || 0}・C(要裁定)${(c.cand || {}).C || 0}・畳まない組 ${c.keepApart}` +
      ` / md は正本の生成物と 1 字一致・禁止語 0・観測版と DFM 版をまたぐ候補 0・候補の本はすべて内蔵に残る(畳んでいない)` +
      (J && J.retired ? ` / 退役 ${J.retired.presets.length} 本は内蔵に残り署名が凍結の写しと同じ・名指しする器 ${J.retired.harnesses.length} 本(${Object.entries(J.retired.kindCounts).map(([k, v]) => k + ' ' + v).join('・')})` : '') +
      (bad.length ? ` / **違反 ${bad.length} 件**: ${bad.slice(0, 5).join(' , ')}` : ''));
  }
}

// ---- 0a3s) 第271便a(第61報・R3): docs.assessedStageH4 ----
// ----   **3 段登録系の正式判定段が h/4 である**ことを機械固定する(fs のみ)。
// ----   統括の検証項目 R3: docs/CALIBRATION_VERDICT_v1.44.md §5.13′.2 は「判定段 h/4・
// ----   ε̂=|Q_{h/2}−Q_{h/4}|/(2^p−1)」と書いていたのに、器の正式門は `value: q.meas`(**h 段**)・
// ----   ε_num=|Q_h−Q_{h/4}| で判定していた(**文書とコードの不一致**)。AD4 の既決どおり h/4 へ統一した。
// ----     ① 3 段登録表の preset で 3 段が揃った量は `assessedStage==='h4'` で、
// ----        判定値 `gate.assessedValue` が **Q_{h/4}** である(σ 倍もその値から出ている)。
// ----     ② h 段の値は `gate.coarseValue`・|Q_h−Q_{h/4}| は `gate.coarseNumBound` に**履歴として残る**。
// ----     ③ 門が読む ε_num は **|Q_{h/2}−Q_{h/4}|**(最終 2 段差)で、
// ----        **ε̂ = 最終 2 段差 / (2^p−1)** が定義どおり再計算できる。
// ----     ④ **登録表の外(2 段だけ)の系の扱いは変えていない**(判定段は h のまま)。
// ----     ⑤ **次数推定の適用条件**: 連続 2 段差が同符号でない列・3 段完全一致の列は
// ----        `orderNotEstimable(…)` で**保留**(convergence.ok が立たない)。
// ----     ⑥ 文書(§5.17)に h/4 の宣言と旧新の値が並記され、§5.16.3 の「判定値は h 段」が訂正済み。
// ----   **書かないこと**: 「判定段を変えたので判定が増えた」「h/4 にしたので収束した」。
{
  const bad = [];
  let nH4 = 0, nH8 = 0, nOther = 0, moved = [];
  try {
    const C = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'out', 'calaudit-w249.json'), 'utf8'));
    const regIds = new Set(((C.threeStageRegistry || {}).rows || []).map((z) => z.id));
    if (!regIds.size) bad.push('①3 段登録表が読めない');
    for (const p of (C.presets || [])) for (const q of (p.quantities || [])) {
      const g = q.gate; const ds = q.dtStages;
      if (!g || !ds || !Number.isFinite(ds.dtQuarter)) continue;
      if (regIds.has(p.id)) {
        // 第272便a(AG1): **条件を満たした量だけ h/8 へ昇格する**。
        //   昇格した量の検査は `docs.h8Rule` が行うので、ここでは
        //   **h4 のままの量だけ**を R3 の定義で固める(h8 は除外して数える)。
        if (g.assessedStage === 'h8') {
          if (!(q.h8 && q.h8.promoted === true))
            bad.push(`①${p.id}|${q.kind} が h8 なのに AG1 の昇格記録が無い`);
          nH8++; continue;
        }
        if (q.assessedStage !== 'h4' || g.assessedStage !== 'h4') {
          bad.push(`①${p.id}|${q.kind} の判定段が h4 でも h8 でもない(${g.assessedStage})`); continue;
        }
        nH4++;
        if (!(Math.abs(g.assessedValue - ds.dtQuarter) <= Math.abs(ds.dtQuarter) * 1e-15))
          bad.push(`①${p.id}|${q.kind} の判定値が Q_{h/4} でない`);
        if (!(Math.abs(g.coarseValue - ds.dt) <= Math.abs(ds.dt) * 1e-15))
          bad.push(`②${p.id}|${q.kind} の coarseValue が Q_h でない`);
        const coarse = Math.abs(ds.dt - ds.dtQuarter);
        if (!(Math.abs(g.coarseNumBound - coarse) <= coarse * 1e-9 + 1e-300))
          bad.push(`②${p.id}|${q.kind} の coarseNumBound が |Q_h−Q_{h/4}| でない`);
        const last = Math.abs(ds.dtHalf - ds.dtQuarter);
        const c = g.convergence || {};
        if (!(Math.abs(c.lastDiff - last) <= last * 1e-9 + 1e-300))
          bad.push(`③${p.id}|${q.kind} の最終 2 段差が |Q_{h/2}−Q_{h/4}| でない`);
        if (Number.isFinite(c.order) && c.order > 0 && Number.isFinite(c.epsHat)) {
          const eps = last / (Math.pow(2, c.order) - 1);
          if (!(Math.abs(c.epsHat - eps) <= Math.abs(eps) * 1e-9 + 1e-300))
            bad.push(`③${p.id}|${q.kind} の ε̂ が定義と合わない`);
        }
        // 第271便a(AF16): 文言は正本の辞書(`contracts.texts`)へまとめたので、**鍵が解けること**を見る。
        const rRef = c.orderEstimableRuleRef || null;
        const texts = (C.contracts || {}).texts || {};
        if (!(c.orderEstimableRule || (rRef && texts[rRef])))
          bad.push(`⑤${p.id}|${q.kind} に次数推定の適用条件が無い`);
        else if (rRef && String(texts[rRef]).indexOf('同符号') < 0)
          bad.push(`⑤${p.id}|${q.kind} の適用条件に「同符号」が書かれていない`);
        if (c.orderEstimable === false && c.ok === true)
          bad.push(`⑤${p.id}|${q.kind} は次数不明なのに収束済みになっている`);
        if (Number.isFinite(g.nSigma) && Number.isFinite(g.sigma) && Number.isFinite(q.obs)
          && !(Math.abs(Math.abs(g.assessedValue - q.obs) / g.sigma - g.nSigma) <= 1e-6 * (1 + g.nSigma)))
          bad.push(`①${p.id}|${q.kind} の σ 倍が判定段の値から出ていない`);
      } else {
        nOther++;
        if (q.assessedStage === 'h4' || q.assessedStage === 'h8'
          || (g.assessedStage && g.assessedStage !== 'h'))
          bad.push(`④登録表の外の系で判定段が動いている(${p.id}|${q.kind})`);
      }
    }
    if (!(nH4 > 0)) bad.push('①h/4 で判定した量が 1 つも無い');
    const md = fs.readFileSync(path.join(ROOT, 'docs', 'CALIBRATION_VERDICT_v1.44.md'), 'utf8');
    const head = md.indexOf('### 5.17 ');
    const sec = (head >= 0) ? md.slice(head, (() => {
      const j = md.indexOf('\n### ', head + 5); return (j < 0) ? md.length : j; })()) : '';
    if (!sec) bad.push('⑥§5.17(第271便a の節)が無い');
    else {
      if (sec.indexOf('h/4') < 0) bad.push('⑥§5.17 に判定段 h/4 の宣言が無い');
      if (sec.indexOf('13925.5846') < 0) bad.push('⑥§5.17 に 📡 の h/4 段の値(13925.5846)が無い');
      if (sec.indexOf('13925.5269') < 0) bad.push('⑥§5.17 に h 段の旧値(13925.5269)が並記されていない');
    }
    const i163 = md.indexOf('#### 5.16.3'), i164 = md.indexOf('#### 5.16.4');
    if (i163 >= 0 && i164 > i163 && /判定値は h 段/.test(md.slice(i163, i164)))
      bad.push('⑥§5.16.3 に「判定値は h 段」が残っている(訂正されていない)');
    moved = ((C.fourValues || {}).whatMoved || []).filter((z) => /R3/.test(z));
    if (!moved.length) bad.push('①fourValues.whatMoved に R3 の記録が無い');
  } catch (e) { bad.push('判定段が読めない: ' + String(e).slice(0, 90)); }
  add('docs.assessedStageH4', bad.length === 0,
    `**3 段登録系の正式判定段は h/4**(第271便a・統括の検証項目 R3 —— 文書 §5.13′.2 は h/4 と`
    + `書いていたのに器は h 段で判定していた。**AD4 の既決どおり h/4 へ統一した**): `
    + `判定値 = Q_{h/4}・最終 2 段差 = |Q_{h/2}−Q_{h/4}|・ε̂ = 最終 2 段差/(2^p−1)(p の定義は不変)/ `
    + `**h 段の値は \`coarseValue\`・|Q_h−Q_{h/4}| は \`coarseNumBound\` に履歴として残す** / `
    + `**登録表の外(2 段だけ)の系の扱いは変えていない** / `
    + `次数は**連続 2 段差が同符号のときだけ**推定する(非単調列・3 段完全一致は `
    + `\`orderNotEstimable\` で保留)/ 判定段 h/4 の量 ${nH4} 件・`
    + `第272便a(AG1)で h/8 へ昇格した量 ${nH8} 件(検査は \`docs.h8Rule\`)・`
    + `登録外の 3 段の量 ${nOther} 件`
    + (bad.length ? ` / **違反 ${bad.length} 件**: ${bad.slice(0, 5).join(' , ')}` : ''));
}

