// ---- 8c) 第11次裁定(2026-07-22): E13 帯状重力補正のQA(v1.28 でルート昇格)----
// 対象に E13 がある場合のみ実行(ルート版は昇格まで対象外 — QA 項目数は対象により変わる)




















































































































































































































































// ---- 8c1) 第280便e(原仮定者の裁定(第70報)「saturnZonalD(68): 観測値版で問題が出ている理由を調査する」・
// ----   統括の検証項目 R67): **📡 D68 の問題の分解**の 4 ブロック。**root(診断コピーの無い世代)では SKIP**。
// ----   ① docs.d68Decomp …… 正本 tests/out/d68-w280e.json(来歴 w272e-1)の分解の数(独立計算・実エンジン・
// ----      正式値のビット再現)と CALIBRATION_VERDICT §5.34・PHYSICS〔第280便e〕の記載が一致する。
// ----   ② behavior.d68Consistent …… 内蔵の診断コピー 2 本(🧷 saturnD68Consistent・📎 saturnD68ObsOrbit)の
// ----      初期状態が純関数 tests/lib-w280e-d68.mjs の構成とビット一致し、正式の抽出器・同じ窓の h 段の近点移動が
// ----      正本の値と一致する(principle・較正母集団の外・門の器の CFG に未登録)。
// ----   ③ lint.zonalApsidal …… 解析ヘルパ zonalApsidal の C が帯状分の Ω²・κ² に掛かり(旧 C·(Ω−κ) ではない)、
// ----      C=1 の値は旧式とビット同一・任意の ε で純関数の円軌道極限と一致・HUD も C を内側で渡す。
// ----   ④ ui.d68Naming …… 📡 の名前から「精密較正」を外し、解析式への fit と実軌道の照合を分けた名前・語にした。
{
  const htmlSrc = fs.readFileSync(path.join(ROOT, TARGET), 'utf8');
  const hasW280e = htmlSrc.indexOf('id:"saturnD68Consistent"') >= 0;
  if (!hasW280e) {
    console.log('SKIP docs.d68Decomp / behavior.d68Consistent / lint.zonalApsidal / ui.d68Naming(対象に第280便e の診断コピーなし — root 等)');
  } else {
    const L68 = await import('file://' + path.join(ROOT, 'tests', 'lib-w280e-d68.mjs'));
    let J68 = null;
    try { J68 = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'out', 'd68-w280e.json'), 'utf8')); } catch { J68 = null; }
    // ---- ① docs.d68Decomp
    {
      const bad = [];
      let sum = '';
      if (!J68) bad.push('正本 d68-w280e.json が読めない');
      else {
        if (!J68.meta || J68.meta.provenanceVersion !== 'w272e-1') bad.push('来歴の版');
        const rep = J68.reproduction || [];
        if (rep.length !== 3 || !rep.every((r) => r.diff === 0)) bad.push('正式値(d68-w268a)のビット再現が 3 段で 0 差でない');
        const E = Object.fromEntries((J68.engine || []).map((r) => [r.key, r]));
        const last = (k) => (E[k] ? E[k].stages[E[k].stages.length - 1] : null);
        for (const k of ['formal11', 'pair', 'geo3scalar11', 'eps01lpn0_11', 'pairLpn0', 'pairEps01', 'pairEps01Lpn0',
          'consistent', 'obsOrbit', 'consistentC1']) {
          const s = last(k);
          if (!s) { bad.push('条件が無い ' + k); continue; }
          if (!(s.windowComplete && s.nFitUsed === 58 && !s.nan && s.clamp === 0 && s.dup === 0 && s.jump === 0)) bad.push('窓/抽出 ' + k);
        }
        if (E.consistent && E.consistent.ranAs !== 'preset') bad.push('🧷 が内蔵の ID で走っていない');
        if (E.obsOrbit && E.obsOrbit.ranAs !== 'preset') bad.push('📎 が内蔵の ID で走っていない');
        // 独立計算とエンジン(2 天体・λPN=0)の差は刻みの幅の内側(0.02 deg/yr)
        for (const k of ['pairLpn0', 'pairEps01Lpn0']) if (!(Math.abs(E[k].engineMinusIndependentDegPerYear) < 0.02)) bad.push('独立計算との差 ' + k);
        const I = J68.independent, D = J68.engineDecomp;
        const circ05 = I.circular[0].rateDegPerDay, circ0 = I.circular[2].rateDegPerDay, cur = I.orbits[0];
        const f = (x, n) => x.toFixed(n);
        const sgn = (x, n) => (x >= 0 ? '+' : '−') + Math.abs(x).toFixed(n);
        const need = [f(cur.meanRKm, 2), f(cur.rateDegPerDay, 4), f(circ05, 4), f(circ0, 4),
          sgn(D.initialGeometryDegPerYear, 2), sgn(D.softening005to001DegPerYear, 2), sgn(D.otherParticlesDegPerYear, 3),
          f(last('formal11').degPerYear, 4), f(last('consistent').degPerYear, 4), f(last('obsOrbit').degPerYear, 4),
          f(last('consistentC1').degPerYear, 4)];
        const V = fs.readFileSync(path.join(ROOT, 'docs', 'CALIBRATION_VERDICT_v1.44.md'), 'utf8');
        const a = V.indexOf('### 5.34 第280便e'), b = (a >= 0) ? V.indexOf('\n## ', a) : -1;
        const sec = (a >= 0) ? V.slice(a, b > a ? b : undefined) : '';
        const Pd = fs.readFileSync(path.join(ROOT, 'docs', 'PHYSICS.md'), 'utf8');
        const pa = Pd.indexOf('〔第280便e'), pb = (pa >= 0) ? Pd.indexOf('\n## 7. 論文', pa) : -1;
        const psec = (pa >= 0) ? Pd.slice(pa, pb > pa ? pb : undefined) : '';
        if (!sec) bad.push('§5.34 が無い');
        if (!psec) bad.push('PHYSICS〔第280便e〕が無い');
        for (const s of need) { if (sec.indexOf(s) < 0) bad.push('§5.34 に ' + s + ' が無い'); if (psec.indexOf(s) < 0) bad.push('PHYSICS に ' + s + ' が無い'); }
        sum = `正式 h/4 ${f(last('formal11').degPerYear, 4)}・🧷 ${f(last('consistent').degPerYear, 4)}・📎 ${f(last('obsOrbit').degPerYear, 4)}・C=1 ${f(last('consistentC1').degPerYear, 4)} deg/yr / `
          + `分解: 初速 ${sgn(D.initialGeometryDegPerYear, 2)}・ε ${sgn(D.softening005to001DegPerYear, 2)}・他の環粒子 ${sgn(D.otherParticlesDegPerYear, 3)}・1PN ${sgn(D.pn1DegPerYear, 3)} deg/yr / `
          + `独立: 平均半径 ${f(cur.meanRKm, 2)} km・${f(cur.rateDegPerDay, 4)} °/日・a の円軌道極限 ε=0.05 ${f(circ05, 4)}・ε=0 ${f(circ0, 4)} °/日`;
      }
      add('docs.d68Decomp', bad.length === 0,
        '**📡 D68 の問題の分解**(第280便e・R67): ' + sum + (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.slice(0, 5).join(' , ')}` : ' / 正本 ↔ §5.34 ↔ PHYSICS 一致・正式値ビット再現'));
    }
    // ---- ② behavior.d68Consistent
    {
      const want = { cons: L68.d68ConsistentIc(), obs: L68.d68ObsOrbitIc(25, 67627) };
      const r = await page.evaluate((w) => {
        const out = {};
        const run1 = (id) => {
          const p = HP.allPresets().find((q) => q.id === id);
          if (!p) return null;
          const v = HP.validatePreset(JSON.parse(JSON.stringify(p)));
          HP.sim.build(v.preset);
          const S = HP.sim, dt = 0.016, nSteps = Math.round(10698.816 / dt);
          const x0 = S.x[1], vy0 = S.vy[1], n0 = S.n, eps = S.params.softening, calib = S.zonal ? S.zonal.calib : null;
          const A = []; let rd1 = 0, th1 = 0, rMin = Infinity, rMax = -Infinity;
          for (let k = 0; k < nSteps; k++) {
            S.step(dt);
            const dx = S.x[1] - S.x[0], dy = S.y[1] - S.y[0], rr = Math.hypot(dx, dy), th = Math.atan2(dy, dx);
            const rd = (dx * (S.vx[1] - S.vx[0]) + dy * (S.vy[1] - S.vy[0])) / rr;
            if (rr < rMin) rMin = rr; if (rr > rMax) rMax = rr;
            if (k >= 1 && rd1 < 0 && rd >= 0) { const fr = -rd1 / (rd - rd1); let a1 = th1, a2 = th;
              while (a2 - a1 > Math.PI) a2 -= 2 * Math.PI; while (a2 - a1 < -Math.PI) a2 += 2 * Math.PI;
              A.push({ ang: a1 + fr * (a2 - a1), k: k - 1 + fr, r: rr }); }
            rd1 = rd; th1 = th;
          }
          return { cls: p.sampleClass, group: p.group, emoji: p.emoji, x0, vy0, n0, eps, calib, A, rMin, rMax,
            nan: S.hasNaN(), pRef: 2 * Math.PI * Math.sqrt(Math.pow(x0, 3) / (v.preset.physics.G * S.m[0])) };
        };
        out.cons = run1('saturnD68Consistent'); out.obs = run1('saturnD68ObsOrbit');
        out.emojiCount = {};
        for (const p of HP.allPresets()) if (p.emoji === '🧷' || p.emoji === '📎') out.emojiCount[p.emoji] = (out.emojiCount[p.emoji] || 0) + 1;
        HP.loadPreset('saturn', false);
        return out;
      }, want);
      const PW = await import('file://' + path.join(ROOT, 'tests', 'lib-w269a-periwindow.mjs'));
      const JG = await import('file://' + path.join(ROOT, 'tests', 'lib-w268a-judgement.mjs'));
      const bad = [];
      const vals = {};
      for (const [k, id, key] of [['cons', 'saturnD68Consistent', 'consistent'], ['obs', 'saturnD68ObsOrbit', 'obsOrbit']]) {
        const z = r[k];
        if (!z) { bad.push('内蔵に無い ' + id); continue; }
        if (z.cls !== 'principle') bad.push(id + ' が principle でない');
        if (z.x0 !== want[k].rp || z.vy0 !== want[k].vp) bad.push(id + ' の初期状態が純関数の構成とビット一致しない');
        if (z.n0 !== 2 || z.eps !== 0.01 || z.calib !== 1.000302283) bad.push(id + ' の条件(2 天体・ε 0.01・既存 C)');
        const fs1 = PW.fitPeriastronStage({ raw: z.A, rMin: z.rMin, rMax: z.rMax, pRef: z.pRef, dt: 0.016, nFit: 58 });
        const dpy = JG.precessionDegPerYear({ degPerOrbit: fs1.slopeDegPerOrbit, pPeriSec: fs1.perMeanSim * 100 });
        vals[k] = dpy;
        const canon = J68 && (J68.engine || []).find((e) => e.key === key);
        const ch = canon ? canon.stages[0].degPerYear : null;
        if (!(fs1.windowComplete && !z.nan)) bad.push(id + ' の窓');
        if (!(ch !== null && Math.abs(dpy - ch) <= 1e-9 * Math.abs(ch))) bad.push(`${id} の h 段 ${dpy} ≠ 正本 ${ch}`);
      }
      const calSrc = fs.readFileSync(path.join(ROOT, 'tests', 'exp-w249b-calaudit.mjs'), 'utf8');
      if (/saturnD68Consistent|saturnD68ObsOrbit/.test(calSrc)) bad.push('門の器 calaudit に診断コピーが登録されている');
      if (r.emojiCount['🧷'] !== 1 || r.emojiCount['📎'] !== 1) bad.push('絵文字が一意でない');
      add('behavior.d68Consistent', bad.length === 0,
        `**📡 の診断コピー 2 本**(第280便e): 🧷 saturnD68Consistent(e*=0.001)h 段 ${vals.cons !== undefined ? vals.cons.toFixed(6) : '—'}・`
        + `📎 saturnD68ObsOrbit(r=a∓ae)h 段 ${vals.obs !== undefined ? vals.obs.toFixed(6) : '—'} deg/yr(正式の抽出器・58 近点窓・正本と一致)/ `
        + `初速は純関数の構成とビット一致・principle・門の器に未登録(**C は D68 の ϖ̇ への既存 fit —— 観測一致とは書かない**)`
        + (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.slice(0, 5).join(' , ')}` : ''));
    }
    // ---- ③ lint.zonalApsidal
    {
      const bad = [];
      const fnA = htmlSrc.indexOf('function zonalApsidal(mu, refR, J, a, calib, eps)');
      const fnB = (fnA >= 0) ? htmlSrc.indexOf('\n}', fnA) : -1;
      const fn = (fnA >= 0) ? htmlSrc.slice(fnA, fnB) : '';
      if (!fn) bad.push('zonalApsidal(… calib, eps) が無い');
      if (fn.indexOf('Math.sqrt(1+C*sO)') < 0 || fn.indexOf('Math.sqrt(1+C*sK)') < 0) bad.push('C が帯状分の Ω²・κ² に掛かっていない');
      if (/\(calib\|\|1\)\*\(omega-kappa\)/.test(fn)) bad.push('旧 C·(Ω−κ) が残っている');
      if (htmlSrc.indexOf('zonalApsidal(sim.params.G*sim.m[Z.i], Z.refR, Z.J, ba, Z.calib||1)') < 0) bad.push('HUD が C を内側で渡していない');
      const D = L68.D68_DECL;
      const hv = await page.evaluate((d) => {
        const mu = d.G * d.M, k = 864 * 180 / Math.PI;
        return { c1: HP.zonal.apsidal(mu, d.refR, d.J, d.aDecl, 1).apsidal * k,
          cC: HP.zonal.apsidal(mu, d.refR, d.J, d.aDecl, d.calib).apsidal * k,
          cE: HP.zonal.apsidal(mu, d.refR, d.J, d.aDecl, d.calib, 0.05).apsidal * k,
          c1bits: (() => { const n0 = Math.sqrt(mu / (d.aDecl ** 3)); let sO = 0, sK = 0;
            const P0 = { 2: -1 / 2, 4: 3 / 8, 6: -5 / 16, 8: 35 / 128, 10: -63 / 256, 12: 231 / 1024 };
            for (const l of [2, 4, 6, 8, 10, 12]) { const A = -d.J[l] * P0[l], z = A * Math.pow(d.refR / d.aDecl, l);
              sO += (l + 1) * z; sK += (l + 1) * (1 - l) * z; }
            return (n0 * Math.sqrt(1 + sO) - n0 * Math.sqrt(1 + sK)) * k; })() };
      }, { G: D.G, M: D.M, refR: D.refR, J: D.J, aDecl: D.aDecl, calib: D.calib });
      const P = (eps) => ({ G: D.G, M: D.M, refR: D.refR, calib: D.calib, J: D.J, eps });
      const lib0 = L68.circularLimit(D.aDecl, P(0)), lib05 = L68.circularLimit(D.aDecl, P(0.05));
      const k = 864 * 180 / Math.PI;
      const fix = hv.cC - D.calib * hv.c1;
      if (hv.c1 !== hv.c1bits) bad.push('C=1 の値が旧式とビット同一でない');
      if (!(Math.abs(hv.cC - lib0.rate * k) < 1e-10)) bad.push('ε=0 で純関数と不一致');
      if (!(Math.abs(hv.cE - lib05.rate * k) < 1e-10)) bad.push('ε=0.05 で純関数と不一致');
      if (!(fix > 9.2e-6 && fix < 9.4e-6)) bad.push('C の位置の差 ' + fix);
      add('lint.zonalApsidal', bad.length === 0,
        `**解析ヘルパ zonalApsidal の C の位置**(第280便e・R67): Ω²=Ω0²+C·ΔΩ²・κ²=κ0²+C·Δκ² → Ω−κ。D68(a=67627 km)で `
        + `新 ${hv.cC.toFixed(7)} − 旧 C·(Ω−κ) ${(D.calib * hv.c1).toFixed(7)} = ${fix.toExponential(4)} °/日・C=1 は旧式とビット同一・`
        + `ε=0.05 の円軌道極限 ${hv.cE.toFixed(7)} °/日(純関数と一致)・HUD も C を内側で渡す`
        + (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.slice(0, 5).join(' , ')}` : ''));
    }
    // ---- ④ ui.d68Naming
    {
      const bad = [];
      const nm = await page.evaluate(() => {
        const p = HP.allPresets().find((q) => q.id === 'saturnZonalD68');
        return { ja: p.name, en: (p.en || {}).name, obs: JSON.stringify(p.obsCard) + JSON.stringify((p.en || {}).obsCard),
          desc: JSON.stringify(p.descStruct) + JSON.stringify((p.en || {}).descStruct) };
      });
      if (/精密較正|精密一致/.test(nm.ja + nm.obs + nm.desc)) bad.push('📡 に「精密較正/精密一致」が残る');
      if (nm.ja.indexOf('帯状重力の照合') < 0) bad.push('ja 名に「帯状重力の照合」が無い');
      if (!/Zonal-Gravity Comparison/.test(nm.en || '') || /Calibrated/.test(nm.en || '')) bad.push('en 名');
      if (nm.obs.indexOf('解析式(J一次永年理論)への fit') < 0) bad.push('obsCard の fit 行');
      if (/D68 精密較正\(C=1\.000302283\)/.test(htmlSrc)) bad.push('変種名に「D68 精密較正」が残る');
      const rd = fs.readFileSync(path.join(ROOT, 'README.md'), 'utf8');
      if (/D68精密較正/.test(rd)) bad.push('README に旧名');
      add('ui.d68Naming', bad.length === 0,
        `**📡 の名前**(第280便e): 「${nm.ja}」/「${nm.en}」—— 解析式への fit(C)と実軌道の照合(門の判定)を分けた名前・語`
        + (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.join(' , ')}` : ''));
    }
  }
}

// ---- 8c1b) 第281便c(原仮定者の裁定(第71報)「浮遊惑星の質量算出根拠を調べ、ダークローターを恒星質量程度に調整して当てはめ、
// ----   DFM 版銀河の質量に計上する」・統括の検証項目 R74): **条件付き質量台帳**の 2 ブロック。**root(宣言の無い世代)では SKIP**。
// ----   ① docs.rotorLedger …… 正本 tests/out/rotorledger-w281c.json(来歴 w272e-1)を、いまの html の 🛞 の bodies から
// ----      純関数 tests/lib-w281c-rotorledger.mjs で引き直した値と**相対 1e-12** で照合し(JSON 文字列一致にしない —— Node 22/24)、
// ----      PHYSICS〔第281便c〕の表に同じ書式の数が載っている・出典(NASA の URL・arXiv 3 番号・未取得の明記)がある・
// ----      「言わないこと」より前に禁止の言い回しが 0・減光と偏向の分離(ビット一致)と質量比例(2 倍・4 倍)の実測が正本にある。
// ----   ② preset.massLedger …… 🛞 の表示専用の宣言 massLedger の型(version・3 行・0.1/1/10 M☉・既定 "none"・rotorInFStar:false)、
// ----      bodies との整合(f★M★ = 恒星の宣言質量・気体・中心核)、内蔵で宣言するのは 🛞 の 1 本だけ、検証器の拒否
// ----      (オブジェクトでない・rotorInFStar:true・二重加算した合計・未知の鍵は警告・既定の不正値は "none" へ)、
// ----      physics・bodies は不変(presetSigHash が基点 53aaa64 の 1a98b3d3 のまま・massLedger を外しても同じ署名)。
{
  const htmlSrc = fs.readFileSync(path.join(ROOT, TARGET), 'utf8');
  // 第282便d: 🛞 の台帳は f★=1 で再宣言(version "w282d-1")—— 第281便c の世代("w281c-1")も読む
  const hasW281c = htmlSrc.indexOf('massLedger:{version:"w281c-1"') >= 0 || htmlSrc.indexOf('massLedger:{version:"w282d-1"') >= 0;
  const has282dML = htmlSrc.indexOf('massLedger:{version:"w282d-1"') >= 0;
  const has283fML = htmlSrc.indexOf('massLedger:{version:"w283f-1"') >= 0   // 第283便f: 💮 の台帳(darkRotor つき)
    || htmlSrc.indexOf('massLedger:{version:"w284a-1"') >= 0;   // 第284便a: 💮 の台帳の版が w284a-1(nTrue・radii)に上がっても宣言する内蔵は同じ 3 本
  if (!hasW281c) {
    console.log('SKIP docs.rotorLedger / preset.massLedger(対象に第281便c の massLedger なし — root 等)');
  } else {
    const LR = await import('file://' + path.join(ROOT, 'tests', 'lib-w281c-rotorledger.mjs'));
    let JR = null;
    try { JR = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'out', 'rotorledger-w281c.json'), 'utf8')); } catch { JR = null; }
    const pdNow = await page.evaluate(() => {
      const p = HP.allPresets().find((q) => q.id === 'ngc3198DFM');
      return p ? JSON.parse(JSON.stringify({ bodies: p.bodies, massCalibration: p.massCalibration, scaleExp: p.scaleExp })) : null;
    });
    // ---- ① docs.rotorLedger
    {
      const bad = [];
      let sum = '';
      if (!JR) bad.push('正本 rotorledger-w281c.json が読めない');
      else if (!pdNow) bad.push('🛞 ngc3198DFM が無い');
      else {
        if (!JR.meta || JR.meta.provenanceVersion !== 'w272e-1') bad.push('来歴の版');
        const rel = LR.relDiff;
        const g = LR.massGroupsFromPreset(pdNow);
        const led = LR.rotorLedger(g), ffp = LR.ffpObsRow(g, led);
        const e75 = LR.lensEtaTable({ mLensEarth: 0.75 }), e37 = LR.lensEtaTable({ mLensEarth: 0.37 });
        let worst = 0;
        const cmp = (a, b, what) => { const r = rel(a, b); if (!(r <= 1e-12)) bad.push('引き直しの差 ' + what + ' ' + r.toExponential(2)); worst = Math.max(worst, Number.isFinite(r) ? r : 1); };
        for (const k of ['starBase', 'fStar', 'gas', 'core', 'unitKg', 'totalUnit']) cmp(g[k], JR.groups[k], 'groups.' + k);
        cmp(led.current.totalUnit, JR.ledger.current.totalUnit, 'current.totalUnit');
        cmp(led.current.totalSun, JR.ledger.current.totalSun, 'current.totalSun');
        cmp(led.nRotor, JR.ledger.nRotor, 'nRotor');
        led.rows.forEach((r, k) => { for (const f of ['mRotorSun', 'nRotor', 'mRotorUnit', 'totalUnit', 'totalSun']) cmp(r[f], JR.ledger.rows[k][f], `rows[${k}].${f}`); });
        for (const f of ['fracOfStarMass', 'addUnit', 'addUnitLo', 'addUnitHi']) cmp(ffp[f], JR.ffpObs[f], 'ffp.' + f);
        [[e75, JR.eta.mLens075], [e37, JR.eta.mLens037]].forEach(([a, b], j) => a.rows.forEach((r, k) => {
          for (const f of ['eta', 'tEDaysEta1', 'thetaEMuasEta1', 'piRelMasForSameThetaE', 'losGapAU']) cmp(r[f], b.rows[k][f], `eta${j}[${k}].${f}`);
        }));
        if (JR.ledger.rotorInFStar !== false) bad.push('正本の rotorInFStar が false でない');
        if (!(JR.declaration && JR.declaration.present && JR.declaration.maxRel <= 1e-12)) bad.push('正本の宣言照合(html の massLedger ↔ 純関数 ≤1e-12)');
        const ls = JR.lightSweepVsDeflection || {};
        if (!(ls.sameDeclVsZero === true && ls.sameDeclVsOne === true && ls.rays >= 20 && ls.heavyBodies >= 1)) bad.push('減光 ↔ 偏向の分離(ビット一致)');
        const lm = JR.lensMassCoupling || {};
        if (!(lm.ratio2x > 1.95 && lm.ratio2x < 2.05 && lm.ratio4x > 3.9 && lm.ratio4x < 4.1 && (lm.rows || []).every((r) => r.lswInvariant === true))) bad.push('偏向の質量比例(2 倍・4 倍)');
        // PHYSICS の表(正本から同じ書式で作った文字列を探す)
        const Pd = fs.readFileSync(path.join(ROOT, 'docs', 'PHYSICS.md'), 'utf8');
        const pa = Pd.indexOf('〔第281便c'), pb = (pa >= 0) ? Pd.indexOf('\n## 7. 論文', pa) : -1;
        const psec = (pa >= 0) ? Pd.slice(pa, pb > pa ? pb : undefined) : '';
        if (!psec) bad.push('PHYSICS〔第281便c〕が無い');
        const toks = LR.docTokens(JR);
        const miss = toks.filter((t) => psec.indexOf(t) < 0);
        if (miss.length) bad.push('PHYSICS の表に無い数 ' + miss.slice(0, 6).join(' '));
        for (const s of ['https://www.nasa.gov/missions/roman-space-telescope/new-study-reveals-nasas-roman-could-find-400-earth-mass-rogue-planets/',
          '2303.08279', '2303.08280', '2507.13794', '未取得(番号のみ)']) if (psec.indexOf(s) < 0) bad.push('出典の記載 ' + s.slice(0, 30));
        const body = psec.split('**言わないこと。**')[0];
        const NG = [/観測一致/, /観測と一致/, /ダークローター[^。\n]{0,15}(検出|発見)/, /浮遊惑星を(検出|発見)した/, /較正した/, /較正を完了/, /新発見/, /創発/, /η\s*を測った/];
        for (const re of NG) if (re.test(body)) bad.push('禁止の言い回し ' + re.source);
        if (!/二重加算しない/.test(body) || !/別集団/.test(body)) bad.push('二重加算の脚注');
        sum = `現状 ${led.current.totalUnit.toFixed(3)} 単位(${LR.fmtSci(led.current.totalSun)} M☉)→ A/B/C `
          + led.rows.map((r) => `${r.totalUnit.toFixed(3)}(${LR.fmtSci(r.totalSun)})`).join(' / ')
          + ` / 観測の行 +${ffp.addUnit.toFixed(4)} 単位(恒星質量の ${(ffp.fracOfStarMass * 100).toFixed(4)}%)`
          + ` / η ${e75.rows.map((r) => LR.fmtSci(r.eta)).join('・')}(η=1 の t_E ${e75.rows.map((r) => r.tEDaysEta1.toFixed(2)).join('/')} 日)`
          + ` / 偏向の質量比 ${lm.ratio2x ? lm.ratio2x.toFixed(3) : '—'}・${lm.ratio4x ? lm.ratio4x.toFixed(3) : '—'} / 引き直しの最大相対差 ${worst.toExponential(1)}`;
      }
      add('docs.rotorLedger', bad.length === 0,
        '**条件付き質量台帳**(第281便c・R74 —— 仮定の 3 シナリオ・既定は追加 0・較正母集団の外): ' + sum
        + (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.slice(0, 6).join(' , ')}` : ' / 正本 ↔ いまの html の引き直し(≤1e-12)↔ PHYSICS 一致・出典あり・禁止の言い回し 0'));
    }
    // ---- ② preset.massLedger
    {
      const bad = [];
      const r = await page.evaluate(() => {
        const p = HP.allPresets().find((q) => q.id === 'ngc3198DFM');
        const v = HP.validatePreset(JSON.parse(JSON.stringify(p)));
        const ml = v.preset.massLedger || null;
        const declared = HP.allPresets().filter((q) => q.massLedger !== undefined).map((q) => q.id);
        const noML = JSON.parse(JSON.stringify(p)); delete noML.massLedger;
        const tryML = (patch) => {
          const q = JSON.parse(JSON.stringify(p));
          q.massLedger = (typeof patch === 'function') ? patch(JSON.parse(JSON.stringify(p.massLedger))) : patch;
          const w = HP.validatePreset(q);
          return { kept: w.ok && w.preset.massLedger !== undefined, warn: (w.warnings || []).filter((s) => /massLedger/.test(s)).length,
            ds: w.ok && w.preset.massLedger ? w.preset.massLedger.defaultScenario : null, sig: HP.presetSigHash(q) };
        };
        return {
          ok: v.ok, warn: (v.warnings || []).filter((s) => /massLedger/.test(s)), ml, declared,
          b: p.bodies, f: p.massCalibration.factorUniform,
          sig: HP.presetSigHash(p), sigNo: HP.presetSigHash(noML),
          rej: {
            notObj: tryML('x'),
            inF: tryML((m) => { m.rotorInFStar = true; return m; }),
            // 第282便d: f★=1 では f★ を M_DR に掛けても値が変わらないので、二重加算の試験は**力学の f**(fDynamics)で作る
            dbl: tryML((m) => { const f = (m.fDynamics !== undefined) ? m.fDynamics : m.fStar; m.rotorScenarios[0].totalUnit = f * (m.starBase + m.rotorScenarios[0].mRotorUnit) + m.gas + m.core; return m; }),
            unk: tryML((m) => { m.foo = 1; return m; }),
            ds: tryML((m) => { m.defaultScenario = 5; return m; }),
            ds1: tryML((m) => { m.defaultScenario = 1; return m; }),
          },
          hp: typeof HP.validateMassLedger === 'function' && (HP.MASS_LEDGER_VERSION === 'w281c-1' || HP.MASS_LEDGER_VERSION === 'w282d-1'),
        };
      });
      const ml = r.ml;
      if (!r.ok || r.warn.length) bad.push('① 🛞 の検証に警告 ' + r.warn.join(' '));
      if (!ml) bad.push('① massLedger が受理されていない');
      else {
        if (ml.version !== (has282dML ? 'w282d-1' : 'w281c-1')) bad.push('① version');
        if (!(Array.isArray(ml.rotorScenarios) && ml.rotorScenarios.length === 3 && ml.rotorScenarios.map((x) => x.mRotorSun).join(',') === '0.1,1,10')) bad.push('① シナリオ 0.1/1/10 の 3 行');
        if (ml.defaultScenario !== 'none') bad.push('① 既定が追加 0("none")でない');
        if (ml.rotorInFStar !== false) bad.push('① 二重加算の宣言 rotorInFStar:false');
        if (!(typeof ml.note === 'string' && ml.note.indexOf('条件付き') >= 0 && typeof ml.noteEn === 'string')) bad.push('① note');
        if (/観測一致|検出した|発見した/.test(ml.note)) bad.push('① note の禁止の言い回し');
        const rel = (a, b) => Math.abs(a - b) / Math.max(Math.abs(b), 1e-300);
        const st = r.b[0], gs = r.b[1], co = r.b[2];
        // 第282便d(第72報③): 台帳の f★ は 1。bodies に焼き込まれた f は fDynamics(旧契約)—— f_dyn·M★ が恒星の宣言質量
        if (has282dML) {
          if (!(ml.fStar === 1 && ml.fDynamics === r.f && rel(ml.fDynamics * ml.starBase, st.n * st.mMin) <= 1e-12)) bad.push('② f★=1・f_dyn·M★ ≠ 恒星の宣言質量');
          if (!(rel(ml.currentTotalUnit, 767.5) <= 1e-12)) bad.push('② f=1 の現状 767.5 単位でない(旧 1147.4 を持ち越した?)');
        } else if (!(rel(ml.fStar * ml.starBase, st.n * st.mMin) <= 1e-12 && ml.fStar === r.f)) bad.push('② f★M★ ≠ 恒星の宣言質量');
        if (!(ml.gas === gs.n * gs.mMin && gs.shell === 'gas' && ml.core === co.m)) bad.push('② 気体・中心核');
        const base = ml.fStar * ml.starBase + ml.gas + ml.core;
        for (const x of ml.rotorScenarios || []) {
          if (!(rel(x.totalUnit, base + x.mRotorUnit) <= 1e-12)) bad.push('② 合計の恒等式 ' + x.mRotorSun);
          if (!(rel(x.mRotorUnit, ml.nRatio * ml.starBase * x.mRotorSun / ml.mStarSun) <= 1e-12)) bad.push('② M_DR = nRatio·M★·⟨m_DR⟩/⟨m★⟩ ' + x.mRotorSun);
          if (!(rel(x.totalSun, x.totalUnit * ml.unitKg / ml.mSunKg) <= 1e-12)) bad.push('② M☉ 換算 ' + x.mRotorSun);
        }
      }
      // 第282便d: 🌚 galaxyAnalogyBH が力学の質量要素(darkRotor)つきの台帳を宣言する —— 2 本
      // 第283便f: 💮 clusterAnalogyBH も darkRotor つきの台帳を宣言する —— 3 本(内蔵の並び順)
      const wantDecl = has283fML ? 'galaxyAnalogyBH,clusterAnalogyBH,ngc3198DFM' : (has282dML ? 'galaxyAnalogyBH,ngc3198DFM' : 'ngc3198DFM');
      if (r.declared.join(',') !== wantDecl) bad.push('③ 宣言する内蔵が ' + wantDecl + ' でない: ' + r.declared.join(','));
      const j = r.rej;
      if (j.notObj.kept || !j.notObj.warn) bad.push('④ オブジェクトでない台帳を落とさない');
      if (j.inF.kept || !j.inF.warn) bad.push('④ rotorInFStar:true を落とさない');
      if (j.dbl.kept || !j.dbl.warn) bad.push('④ 二重加算した合計を落とさない');
      if (!j.unk.kept || !j.unk.warn) bad.push('④ 未知の鍵(警告して残す)');
      if (!j.ds.kept || j.ds.ds !== 'none' || !j.ds.warn) bad.push('④ 既定の不正値 → "none"');
      if (!j.ds1.kept || j.ds1.ds !== 1) bad.push('④ 既定にシナリオの値を受理');
      if (!r.hp) bad.push('HP.validateMassLedger / MASS_LEDGER_VERSION');
      // ⑤ 物理は不変: 署名は基点 53aaa64 の値のまま・台帳の有無・不正な台帳でも署名は同じ
      const SIG0 = '1a98b3d3';
      if (r.sig !== SIG0) bad.push(`⑤ presetSigHash ${r.sig} ≠ 基点 ${SIG0}`);
      if (r.sigNo !== r.sig || Object.values(j).some((x) => x.sig !== r.sig)) bad.push('⑤ massLedger が署名に入っている');
      add('preset.massLedger', bad.length === 0,
        `**🛞 の条件付き質量台帳の宣言**(第281便c・表示専用): 3 シナリオ ${ml ? ml.rotorScenarios.map((x) => x.mRotorSun + ' M☉→' + x.totalUnit.toFixed(1)).join(' / ') : '—'} 単位・`
        + `既定 ${ml ? ml.defaultScenario : '—'}(追加 0)・rotorInFStar ${ml ? ml.rotorInFStar : '—'}(f★ を掛けない別集団)・宣言は ${r.declared.length} 本・`
        + `拒否 3 種と未知の鍵・既定の修正を確認・presetSigHash ${r.sig}(基点と同じ・台帳の有無で不変)`
        + (bad.length ? ` / **食い違い ${bad.length} 件**: ${bad.slice(0, 6).join(' , ')}` : ''));
    }
  }
}

// ---- 8c1c) 第282便d(原仮定者の裁定(第72報)⑥・統括の読み R81・AN17/AN19): **アナロジー便**の 3 ブロック
// ----   (器 tests/exp-w282d-analogy.mjs・正本 tests/out/analogy-w282d.json)。**root(宣言の無い世代)では SKIP**。
