        cases.push(`宣言 ${live.rows.filter((r) => r.on).length}/4(源 ${live.rows.map((r) => r.n0).join('/')}・試験粒子 ${live.rows.map((r) => r.nTp).join('/')}・末尾に連続・質量は宣言どおり・署名に入る)・内蔵 ${live.n} 本のうち宣言は 4 本だけ`);
        const Jt = rd('tests/out/tpsign-w284e.json');
