      mechanism: gm.mech.allAffineErr < 1e-9 && gm.mech.diskAffineErr < 1e-9
        && gm.mech.allMeanErr > 1 && gm.mech.diskMeanErr < 1e-3 && gm.mech.gradErr < 1e-9
